module multi_pipe_4bit(
    input clk, 
    input rst_n, 
    input [3:0] mul_a, 
    input [3:0] mul_b, 
    output [7:0] mul_out
);
// Parameter declaration
parameter size = 4;
// Internal signals
wire [size-1:0] mul_a_ext, mul_b_ext;
wire [size-1:0] partial_product[size-1:0];
reg [7:0] register[0:size-1];
reg [7:0] mul_out_reg;
// Extend inputs
assign mul_a_ext = {{size{1'b0}}, mul_a};
assign mul_b_ext = {{size{1'b0}}, mul_b};
// Generate partial products
generate
    genvar i;
    for(i = 0; i < size; i=i+1) begin : gen_partial_products
        assign partial_product[i] = (mul_b_ext[i]) ? (mul_a_ext << i) : 'd0;
    end
endgenerate
// Sequential logic for registers
integer k;
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        for(k = 0; k < size; k=k+1) begin
            register[k] <= 0;
        end
    end else begin
        register[0] <= partial_product[0];
        for(k = 1; k < size; k=k+1) begin
            register[k] <= register[k-1] + partial_product[k];
        end
    end
end
// Sequential logic for output
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        mul_out_reg <= 0;
    end else begin
        mul_out_reg <= register[size-1];
    end
end
// Assign output
assign mul_out = mul_out_reg;
endmodule
